  'hj2a-l11-w31': 'màikè zhīdào zìjǐ de fāyīn hé shēngdiào dōu bùtàihǎo， xūyào duō liànxí。',
  'hj2a-l11-w32': 'tián fāng tíyì tā hé màikè hùxiāngbāngzhù： tā jiào tā hànyǔ， tā bāng tā liàn yīngyǔ。',
  'hj2a-l11-w33': 'tián fāng xīwàng màikè néng rènzhēn xué hànyǔ， búyào mǎmǎhǔhǔ de。',
  'hj2a-l12-w1': 'guān jiànpíng chū ménqián fāxiàn hùzhào bújiàn le， jí dédào chù fān kǒudài。',
  'hj2a-l12-w2': 'xiàyǔbāng guān jiànpíng zhǎo le bàntiān， cái zài dàyī nèi dài fān chū hùzhào。',
  'hj2a-l12-w3': 'wǒ zhǎo le yīshàngwǔ， zhōngyú zhǎo zhe nà zhāng chūguó qiānzhèng。',
  'hj2a-l12-w4': 'zuótiān huílái nǐ bǎ hùzhào fàng nǎr le， zěnme xiànzài zhǎo búdào？',
  'hj2a-l12-w5': 'qù ōuzhōu lǚxíng， bìxū tíqián bànhǎo qiānzhèng cáinéng chūjìng。',
  'hj2a-l12-w6': 'tā de shǒutíbāo lǐ zhuāng zhe hùzhào、 shǒujī hé jiāmén yàoshi sānyàng zhòngyào wùpǐn。',
  'hj2a-l12-w7': 'zhège xiǎobāo tàixiǎo， sāi bù jìnqù yīběn hòu hùzhào。',
