  'hj2a-l12-w9': 'nǐ hǎohǎoér fān yībiàn dàyī kǒudài， hùzhào hěn kěnéng hái zài lǐmiàn。',
  'hj2a-l12-w10': 'dōngtiān chūmén wǒ zǒng chuān zhèjiàn hēisè dàyī， kǒudài hěn shēn néng fàng zhèngjiàn。',
  'hj2a-l12-w11': 'dàyī nèicè de kǒudài zuì shìhé fàng hùzhào， bù róngyì nòng diū。',
