  'hj2a-l12-w19': 'pángrén juéde qiúmí tōngxiāo kàn qiú bù tài zhèngcháng， tā què lèzàiqízhōng。',
  'hj2a-l12-w20': 'tā zìjǐ yě chéngrèn， kàn qiú shíhuì biàndé géwài kàngfèn。',
  'hj2a-l12-w21': 'dàsài qījiān tā xiàng fākuáng yīyàng， quántiān zhǐ xiǎngzhe qiúsài。',
  'hj2a-l12-w22': 'ōuzhōubēi shì quánqiú guānzhùdù zuìgāo de zúqiú jǐnbiāosài zhīyī。',
